from fastapi import FastAPI

app = FastAPI()

# ❌ DANGEROUS: Returning raw dictionary or ORM object directly leaks
# sensitive internal fields (password_hash, api_keys, is_admin) to the client!
@app.get('/user/{id}')
def get_user(id: int):
  user_db = {'id': id, 'username': 'ada', 'password_hash': '$2b$12$e8...'}
  return user_db # ❌ password_hash is sent over the wire!

from fastapi import FastAPI
from pydantic import BaseModel, EmailStr

app = FastAPI()

class UserPublic(BaseModel):
  id: int
  username: str

# ✅ NEW: FastAPI filters output through UserPublic; password_hash is stripped!
@app.get('/user/{id}', response_model=UserPublic, response_model_exclude_unset=True)
def get_user(id: int):
  user_db = {'id': id, 'username': 'ada', 'password_hash': '$2b$12$e8...'}
  return user_db # ✅ Only 'id' and 'username' are sent to the client
